  LinearLayout head=row();TextView menu=text("☰",25,CYAN,false);menu.setGravity(Gravity.CENTER);head.addView(menu,new LinearLayout.LayoutParams(dp(40),dp(62)));TextView robot=text("▣\n⌁",20,PURPLE,true);robot.setGravity(Gravity.CENTER);robot.setShadowLayer(12,0,0,PURPLE);robot.setBackground(bg(Color.rgb(8,5,20),PURPLE,14,1));head.addView(robot,new LinearLayout.LayoutParams(dp(54),dp(54)));head.addView(spaceH(10));TextView brand=text("MASTER\nRESPONDE",24,Color.WHITE,true);brand.setLineSpacing(-3,1f);head.addView(brand,new LinearLayout.LayoutParams(0,dp(62),1f));LinearLayout rhs=col();TextView ver=text("v2.0.9",10,MUTED,false);ver.setGravity(Gravity.RIGHT);rhs.addView(ver);online=text("● ONLINE",11,GREEN,true);online.setGravity(Gravity.RIGHT);rhs.addView(online);head.addView(rhs,new LinearLayout.LayoutParams(dp(82),-2));root.addView(head);
  TextView protect=text("✓   SOMENTE WHATSAPP BUSINESS      PROTEGIDO   🔒",11,Color.WHITE,true);protect.setGravity(Gravity.CENTER);protect.setPadding(dp(6),dp(10),dp(6),dp(10));protect.setBackground(bg(Color.rgb(2,20,12),GREEN,11,1));root.addView(protect,new LinearLayout.LayoutParams(-1,-2));

  title(root,"STATUS DOS SERVIÇOS");LinearLayout services=row();wa=service(services,"●","WhatsApp\nBusiness",GREEN);acc=service(services,"♿","Acessibilidade",PURPLE);notif=service(services,"◇","Notificações",CYAN);engine=service(services,"⚙","Motor de\nRespostas",CYAN);root.addView(services,new LinearLayout.LayoutParams(-1,-2));

  title(root,"CONTROLE DO BOT");LinearLayout control=card(GREEN);LinearLayout controls=row();Button start=action("▶  ATIVAR BOT",GREEN);start.setOnClickListener(v->{prefs.edit().putBoolean("bot_enabled",true).apply();refresh();});controls.addView(start,new LinearLayout.LayoutParams(0,dp(50),1f));controls.addView(spaceH(8));FrameLayout center=new FrameLayout(this);power=new Button(this);power.setText("⏻");power.setTextSize(34);power.setTextColor(GREEN);power.setShadowLayer(14,0,0,GREEN);power.setBackground(circle(Color.rgb(1,24,12),GREEN,3));power.setOnClickListener(v->{prefs.edit().putBoolean("bot_enabled",!prefs.getBoolean("bot_enabled",false)).apply();refresh();});center.addView(power,new FrameLayout.LayoutParams(dp(92),dp(92),Gravity.CENTER));controls.addView(center,new LinearLayout.LayoutParams(dp(102),dp(98)));controls.addView(spaceH(8));Button pause=action("Ⅱ  PAUSAR BOT",RED);pause.setOnClickListener(v->{prefs.edit().putBoolean("bot_enabled",false).apply();refresh();});controls.addView(pause,new LinearLayout.LayoutParams(0,dp(50),1f));control.addView(controls);LinearLayout mr=row();mode=text("MODO ATUAL: AUTOMÁTICO • ATIVO",10,GREEN,true);mr.addView(mode,new LinearLayout.LayoutParams(0,-2,1f));TextView test=text("MODO TESTE   ○",10,MUTED,false);test.setGravity(Gravity.RIGHT);mr.addView(test,new LinearLayout.LayoutParams(0,-2,1f));control.addView(mr);root.addView(control,new LinearLayout.LayoutParams(-1,-2));

