  root.addView(space(12));LinearLayout security=card(GREEN);LinearLayout sec=row();TextView shield=text("♢\n🔒",27,GREEN,true);shield.setGravity(Gravity.CENTER);shield.setShadowLayer(14,0,0,GREEN);sec.addView(shield,new LinearLayout.LayoutParams(dp(70),dp(96)));LinearLayout checks=col();checks.addView(text("SEGURANÇA MÁXIMA",12,Color.WHITE,true));checks.addView(space(5));checks.addView(text("✓  Somente WhatsApp Business\n✓  Anti-eco ativo\n✓  Proteção contra conversa errada\n✓  Sistema anti-loop ativo",10,Color.WHITE,false));sec.addView(checks,new LinearLayout.LayoutParams(0,-2,1f));TextView safe=text("100%\nSEGURO",14,GREEN,true);safe.setGravity(Gravity.CENTER);safe.setBackground(circle(Color.rgb(2,22,12),GREEN,2));sec.addView(safe,new LinearLayout.LayoutParams(dp(72),dp(72)));security.addView(sec);root.addView(security,new LinearLayout.LayoutParams(-1,-2));

