 private void refresh(){if(prefs==null)return;boolean on=prefs.getBoolean("bot_enabled",false),bi=isBusinessInstalled(),ac=WhatsAppAccessibilityService.isEnabled(this),no=isNotificationAccessEnabled();set(wa,bi?"ATIVO":"OFF",bi);set(acc,ac?"ATIVA":"OFF",ac);set(notif,no?"ATIVAS":"OFF",no);set(engine,on?"ATIVO":"PAUSADO",on);if(mode!=null){mode.setText(on?"MODO ATUAL: AUTOMÁTICO • ATIVO":"MODO ATUAL: PAUSADO");mode.setTextColor(on?GREEN:RED);}if(power!=null)power.setTextColor(on?GREEN:RED);if(online!=null){online.setText(on?"● ONLINE":"● PAUSADO");online.setTextColor(on?GREEN:RED);}setValue(lastChat,prefs.getString("accessibility_last_conversation",""));setValue(lastMsg,prefs.getString("accessibility_last_message",""));setValue(lastReply,prefs.getString("accessibility_last_reply",""));setValue(lastStatus,prefs.getString("accessibility_last_status",""));int p=prefs.getInt("neon_pending_replies",0),s=prefs.getInt("stats_sent_today",0),f=prefs.getInt("stats_failed_today",0),a=prefs.getInt("stats_attempts_today",0),t=prefs.getInt("stats_chats_today",0);if(pending!=null)pending.setText("• Pendentes        "+p);if(sent!=null)sent.setText("• Enviadas          "+s);if(fail!=null)fail.setText("• Falhas               "+f);if(attempts!=null)attempts.setText("• Tentativas        "+a);if(today!=null)today.setText("• Atendimentos   "+t);if(totalSent!=null)totalSent.setText("• Respostas       "+s);if(rate!=null)rate.setText("• Taxa sucesso   "+((s+f)==0?"--":Math.round(100f*s/(s+f))+"%"));if(totalFail!=null)totalFail.setText("• Falhas               "+f);}
 private void setValue(TextView v,String s){if(v!=null)v.setText(value(s));}
 private TextView service(LinearLayout p,String icon,String label,int accent){LinearLayout c=col();c.setGravity(Gravity.CENTER);c.setPadding(dp(3),dp(8),dp(3),dp(8));c.setBackground(bg(CARD,accent,11,1));TextView i=text(icon,23,accent,true);i.setGravity(Gravity.CENTER);i.setShadowLayer(8,0,0,accent);c.addView(i);TextView l=text(label,8,Color.WHITE,true);l.setGravity(Gravity.CENTER);c.addView(l);TextView state=text("...",8,GREEN,true);state.setGravity(Gravity.CENTER);c.addView(state);p.addView(c,new LinearLayout.LayoutParams(0,dp(108),1f));p.addView(spaceH(5));return state;}
 private TextView activityRow(LinearLayout p,String icon,String label){LinearLayout r=row();TextView i=text(icon,12,CYAN,true);r.addView(i,new LinearLayout.LayoutParams(dp(20),-2));r.addView(text(label,10,MUTED,false),new LinearLayout.LayoutParams(dp(116),-2));TextView v=text("—",10,Color.WHITE,true);r.addView(v,new LinearLayout.LayoutParams(0,-2,1f));p.addView(r);p.addView(space(6));return v;}
 private TextView metric(LinearLayout p,String s){TextView t=text("• "+s,9,Color.WHITE,false);t.setPadding(0,dp(6),0,0);p.addView(t);return t;}
 private Button action(String s,int c){Button b=new Button(this);b.setText(s);b.setTextSize(10);b.setTextColor(Color.WHITE);b.setTypeface(Typeface.DEFAULT_BOLD);b.setAllCaps(false);b.setBackground(bg(Color.rgb(7,18,14),c,9,2));return b;}
 private Button nav(String s,int c,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setTextSize(9);b.setTextColor(c);b.setAllCaps(false);b.setBackgroundColor(Color.TRANSPARENT);b.setOnClickListener(l);return b;}
 private LinearLayout card(int accent){LinearLayout l=col();l.setPadding(dp(10),dp(10),dp(10),dp(10));l.setBackground(bg(CARD,accent,11,1));return l;}private void title(LinearLayout r,String s){r.addView(space(14));r.addView(text("—  "+s,11,Color.WHITE,true));r.addView(space(7));}private void set(TextView v,String s,boolean ok){if(v!=null){v.setText(s);v.setTextColor(ok?GREEN:RED);}}private boolean isBusinessInstalled(){try{getPackageManager().getPackageInfo("com.whatsapp.w4b",0);return true;}catch(Throwable t){return false;}}private boolean isNotificationAccessEnabled(){try{String e=Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners");return e!=null&&e.contains(getPackageName());}catch(Throwable t){return false;}}
 private GradientDrawable bg(int fill,int stroke,int radius,int width){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));d.setStroke(dp(width),stroke);return d;}private GradientDrawable circle(int fill,int stroke,int width){GradientDrawable d=bg(fill,stroke,100,width);d.setShape(GradientDrawable.OVAL);return d;}private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}private TextView text(String s,int sp,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(c);t.setTypeface(Typeface.DEFAULT,bold?Typeface.BOLD:Typeface.NORMAL);return t;}private Space space(int x){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(1,dp(x)));return s;}private Space spaceH(int x){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(dp(x),1));return s;}private LinearLayout.LayoutParams weight(){return new LinearLayout.LayoutParams(0,dp(56),1f);}private String value(String s){if(s==null||s.trim().isEmpty())return"—";s=s.trim();return s.length()>52?s.substring(0,49)+"...":s;}private int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
